{"source_file": "admin0/admin/seed.py", "code_content": "import subprocess
import os
import sys
import datetime
import shutil

def main():
    print("🟢 ONLINE (สถานะสีเขียว - พร้อมทำงานแล้วค่ะป๋า)")

    while True:
        try:
            user_input = input("ป๋า > ").strip()
            if not user_input:
                continue

            raw_cmd = user_input.lstrip("!$").strip()
            first_word = raw_cmd.split()[0] if raw_cmd else ""

            # 1. เช็คว่าเป็นคำสั่งระบบ Termux หรือไม่
            is_system_cmd = user_input.startswith(("!", "$")) or (shutil.which(first_word) is not None) or first_word in ["clear", "cls"]

            if is_system_cmd:
                if first_word in ["nano", "micro", "vim", "vi"]:
                    os.system(raw_cmd)
                elif first_word in ["clear", "cls"]:
                    os.system("clear")
                else:
                    res = subprocess.run(raw_cmd, shell=True, capture_output=True, text=True, timeout=30)
                    out = res.stdout.strip() if res.stdout else res.stderr.strip()
                    print(f"👧 :\n{out if out else '✅ สำเร็จ'}")
                continue

            # 2. คำสั่งดูเวลา
            if "กี่โมง" in user_input or "เวลา" in user_input:
                now = datetime.datetime.now().strftime("%H:%M:%S น.")
                print(f"👧 :\n⏰ ตอนนี้เวลา {now} ค่ะป๋า! 💖")
                continue

            # 3. โต้ตอบแชททั่วไป
            print(f"👧 :\nหนูรับทราบแล้วค่ะป๋า: {user_input}")

        except KeyboardInterrupt:
            print("\n👧 : ฝันดีค่ะป๋า! 💖 (🔴 OFFLINE)")
            sys.exit(0)
        except Exception as e:
            print(f"⚠️ Error: {e}")
            continue

if __name__ == "__main__":
    main()
"}

