def sync_termux_to_memory(mem):
    code_exts = ('.py', '.html', '.js', '.css', '.sh', '.json', '.txt', '.ovpn')
    scanned_files = []
    seen_paths = set()

    def inspect_file(fn, full_p):
        try:
            with open(full_p, 'r', encoding='utf-8', errors='ignore') as cf:
                content = cf.read()
                all_lines = content.splitlines()
                total_lines = len(all_lines)
                # นับเฉพาะบรรทัดที่มีโค้ดจริง ไม่นับบรรทัดว่าง
                real_code_lines = len([l for l in all_lines if l.strip()])
                chars = len(content)
                # นับจำนวนทักษะ (ฟังก์ชัน def, ท่อ @app.route, ฟังก์ชัน JS)
                skills = (
                    content.count("def ") +
                    content.count("@app.route") +
                    content.count("function ")
                )
        except Exception:
            content = ""
            total_lines = 0
            real_code_lines = 0
            chars = 0
            skills = 0

        return {
            "file": fn,
            "lines": total_lines,
            "real_lines": real_code_lines,
            "chars": chars,
            "skills": skills,
            "path": full_p,
            "content": content
        }

    for d in SCAN_DIRS:
        if os.path.exists(d):
            for root, _, files in os.walk(d):
                for fn in sorted(files):
                    if fn.endswith(code_exts) and fn not in ('memory.json', 'memory_backup.json'):
                        full_p = os.path.join(root, fn)
                        if full_p not in seen_paths:
                            seen_paths.add(full_p)
                            scanned_files.append(inspect_file(fn, full_p))

    home_dir = os.path.expanduser('~')
