function vBuildDirs(){const map={};vAll.forEach(x=>{const d=getDir(x.path);map[d]=(map[d]||0)+1;});const list=Object.entries(map).sort((a,b)=>b[1]-a[1]);document.getElementById('vDirSel').innerHTML=`<option value="ALL">📁 ทั้งหมด (${vAll.length} รูป)</option>`+list.map(([d,n])=>`<option value="${d}">📂 ${shortDir(d)} (${n})</option>`).join('');document.getElementById('vDirBtns').innerHTML=[['ALL',`📁 ทั้งหมด (${vAll.length})`],...list.map(([d,n])=>[d,`📂 ${shortDir(d)} (${n})`])].map(([d,t])=>`<button type="button" data-d="${d}" onclick="vPickDir(this.dataset.d)" style="white-space:nowrap;padding:5px 10px;border-radius:14px;font-size:11px;flex-shrink:0;border:1px solid #334155;">${t}</button>`).join('');vStyleDirs();}
function vStyleDirs(){document.getElementById('vDirSel').value=vDir;document.querySelectorAll('#vDirBtns button').forEach(b=>{const on=b.dataset.d===vDir;b.style.background=on?'#2563eb':'#1e293b';b.style.color=on?'#fff':'#cbd5e1';});}
function vPickDir(d){vDir=d;vStyleDirs();vFilter();}
function vToggleMode(){vMode=vMode==='grid'?'tbl':'grid';document.getElementById('vGrid').style.display=vMode==='grid'?'grid':'none';document.getElementById('vTbl').style.display=vMode==='tbl'?'table':'none';document.getElementById('vModeBtn').innerText=vMode==='grid'?'📋 ตาราง':'🖼️ รูปเล็ก';vReset();}
function vMore(){if(vIdx>=vSub.length)return;const s=vSub.slice(vIdx,vIdx+80),base=vIdx;vIdx+=s.length;if(vMode==='grid'){document.getElementById('vGrid').insertAdjacentHTML('beforeend',s.map((x,i)=>`<div onclick="vOpen(${base+i})" style="background:#1e293b;border:1px solid #334155;border-radius:6px;padding:3px;"><img src="/api/vision_img?path=${encodeURIComponent(x.path)}" loading="lazy" style="width:100%;height:70px;object-fit:cover;border-radius:4px;display:block;"><div style="font-size:10px;color:#cbd5e1;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;margin-top:2px;text-align:center;">${x.filename}</div></div>`).join(''));}else{document.getElementById('vTbody').insertAdjacentHTML('beforeend',s.map((x,i)=>`<tr onclick="vOpen(${base+i})"><td style="padding:4px;border:1px solid #333;"><img src="/api/vision_img?path=${encodeURIComponent(x.path)}" loading="lazy" style="width:40px;height:40px;object-fit:cover;border-radius:4px;"></td><td style="padding:4px;border:1px solid #333;word-break:break-all;">${x.filename}</td><td style="padding:4px;border:1px solid #333;">${x.size_bytes}</td></tr>`).join(''));}}
function vReset(){vIdx=0;document.getElementById('vGrid').innerHTML='';document.getElementById('vTbody').innerHTML='';document.getElementById('vBox').scrollTop=0;vMore();}
function vScroll(){const b=document.getElementById('vBox');if(b.scrollTop+b.clientHeight>=b.scrollHeight-120)vMore();}
function vFilter(){const q=document.getElementById('vSearch').value.toLowerCase();vSub=vAll.filter(x=>(vDir==='ALL'||getDir(x.path)===vDir)&&(!q||(x.filename&&x.filename.toLowerCase().includes(q))||(x.path&&x.path.toLowerCase().includes(q))));document.getElementById('v-cnt').innerText=vSub.length+' รูป';document.getElementById('v-mb').innerText=(vSub.reduce((s,x)=>s+(x.size_bytes||0),0)/1048576).toFixed(2)+' MB';vReset();}
fetch('/api/vision_index').then(r=>r.json()).then(d=>{vAll=d.items||[];vSub=vAll;document.getElementById('v-cnt').innerText=d.total_images+' รูป';document.getElementById('v-mb').innerText=d.total_size_mb+' MB';vBuildDirs();vReset();});
</script>

