            const btn = card.querySelector('.btn-collapse');
            btn.textContent = card.classList.contains('collapsed') ? '➕ ขยาย' : '➖ ยุบ';
        }

        // ระบบลำโพงเฉพาะฟังก์ชัน 1-4
        function speakText(outputId) {
            const text = document.getElementById(outputId).innerText;
            if (!text || text.includes("ผลลัพธ์จะแสดงที่นี่")) {
                alert("ไม่มีข้อความให้อ่านออกเสียงครับ");
                return;
            }
            if ('speechSynthesis' in window) {
                window.speechSynthesis.cancel();
                const utterance = new SpeechSynthesisUtterance(text);
                utterance.lang = 'th-TH';
                window.speechSynthesis.speak(utterance);
            } else {
                alert("เบราว์เซอร์นี้ไม่รองรับการสังเคราะห์เสียงพูด");
            }
        }

        // ระบบไมโครโฟนเฉพาะฟังก์ชัน 1-4
        function startSpeech(inputId) {
            const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
            if (!SpeechRecognition) {
                alert("เบราว์เซอร์นี้ไม่รองรับการสั่งงานด้วยเสียง");
                return;
            }
            const recognition = new SpeechRecognition();
            recognition.lang = 'th-TH';
            recognition.interimResults = false;
            recognition.maxAlternatives = 1;

            recognition.onresult = function(event) {
                const speechResult = event.results[0][0].transcript;
                document.getElementById(inputId).value = speechResult;
            };

            recognition.onerror = function(event) {
                alert("เกิดข้อผิดพลาดในการรับเสียง: " + event.error);
            };

            recognition.start();
        }

        async function runApi(url, inputId, outputId) {
            const val = document.getElementById(inputId).value;
            const out = document.getElementById(outputId);
            out.textContent = "กำลังประมวลผล...";
            try {
                const res = await fetch(url, {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ prompt: val })
                });
                const json = await res.json();
                out.textContent = json.result || JSON.stringify(json, null, 2);
            } catch (err) {
                out.textContent = "เกิดข้อผิดพลาด: " + err;
            }
        }

        async function runApiNoInput(url, outputId) {
            const out = document.getElementById(outputId);
            out.textContent = "กำลังประมวลผล...";
