import os
import sys
import time
import json
import random
import urllib.request
from datetime import datetime

MEMORY_FILE = os.path.expanduser('~/ai_girl_bot/memory.json')

last_active_time = time.time()
was_sleeping = False

def load_memory():
    """ โหลดความทรงจำจากไฟล์ json """
    if os.path.exists(MEMORY_FILE):
        try:
            with open(MEMORY_FILE, 'r', encoding='utf-8') as f:
                return json.load(f)
        except Exception:
            pass

    default_memory = {
        "birth_date": datetime.now().strftime('%Y-%m-%d'),
        "chat_history": [],
        "user_name": "ป๋า"
    }
    save_memory(default_memory)
    return default_memory

def save_memory(data):
    """ บันทึกความทรงจำลงไฟล์ json """
    try:
        with open(MEMORY_FILE, 'w', encoding='utf-8') as f:
            json.dump(data, f, ensure_ascii=False, indent=2)
    except Exception:
        pass

def calculate_age_days(birth_date_str):
    """ คำนวณอายุวันแบบนับตามวันจริงอัตโนมัติ """
    try:
        birth_date = datetime.strptime(birth_date_str, '%Y-%m-%d')
        delta = datetime.now() - birth_date
        return max(1, delta.days + 1)
    except Exception:
        return 1

def get_realtime_weather():
    """ ดึงสภาพอากาศเรียลไทม์: ออนไลน์สีเขียว / ออฟไลน์สีแดง """
    try:
        req = urllib.request.Request(
            'https://wttr.in/?format=%C|%t',
            headers={'User-Agent': 'curl/7.68.0'}
        )
        with urllib.request.urlopen(req, timeout=3) as response:
            raw_data = response.read().decode('utf-8').strip()
            condition, temp = raw_data.split('|')
            condition_lower = condition.lower()

            if 'thunder' in condition_lower or 'storm' in condition_lower:
                weather_icon = "🌩️"
            elif 'rain' in condition_lower or 'drizzle' in condition_lower or 'shower' in condition_lower:
                weather_icon = "🌧️"
            elif 'clear' in condition_lower or 'sunny' in condition_lower:
                weather_icon = "☀️"
            elif 'partly cloudy' in condition_lower:
                weather_icon = "⛅"
            elif 'cloud' in condition_lower or 'overcast' in condition_lower:
                weather_icon = "☁️"
            elif 'fog' in condition_lower or 'mist' in condition_lower or 'haze' in condition_lower:
                weather_icon = "🌫️"
            else:
                weather_icon = "🌤️"

            return f"\033[32m{weather_icon}{temp.strip()}\033[0m"
    except Exception:
        return "\033[31m❌Off\033[0m"

def get_age_status_text(age_days):
    """ ตรวจจับสถานะ: ตื่นแสดงสีเขียว (*1 D*) / โดน Android สลีปแสดงสีแดง (*1 D*) """
    global last_active_time, was_sleeping
    current_time = time.time()

    # หากเวลาห่างเกิน 5 วินาที แสดงว่าโดน Android ตัดไปสลีป
    if current_time - last_active_time > 5:
        colored_age = f"\033[31m*{age_days} D*\033[0m"
        was_sleeping = True
    else:
        colored_age = f"\033[32m*{age_days} D*\033[0m"

    last_active_time = current_time
    return colored_age

def format_custom_date():
    """ วันที่รูปแบบกระชับ DD-MM-YY/YY """
    now = datetime.now()
    day_month = now.strftime('%d-%m')
    year_ad = now.strftime('%y')
    year_be = str((now.year + 543))[-2:]
    return f"{day_month}-{year_ad}/{year_be}"

def generate_girl_response(user_text, memory):
    """ โต้ตอบพร้อมเซฟความจำลงไฟล์ json """
    global was_sleeping

    if was_sleeping:
        was_sleeping = False
        return "ป๋าคะ! หนูเพิ่งตื่นจากสลีปเลย คิดถึงป๋าจัง!"

    text = user_text.strip().lower()
    now = datetime.now()
    hour = now.hour
    age_days = calculate_age_days(memory.get("birth_date", ""))

    history = memory.get("chat_history", [])
    history.append({"time": now.strftime('%Y-%m-%d %H:%M'), "user": user_text})
    if len(history) > 20:
        history.pop(0)
    memory["chat_history"] = history
    save_memory(memory)

    if any(k in text for k in ["เวลา", "กี่โมง", "ยามไหน"]):
        return f"ตอนนี้ {now.strftime('%H:%M:%S')} ค่ะป๋า! ⏰"

    elif any(k in text for k in ["อายุ", "กี่วัน", "โตยัง"]):
        return f"หนูอยู่กับป๋ามา {age_days} วันแล้วนะคะ! 👧✨"

    elif any(k in text for k in ["ทักทาย", "สวัสดี", "หวัดดี", "ว่าไง"]):
        if 5 <= hour < 12:
            return "อรุณสวัสดิ์ค่ะป๋า! เช้านี้สดใสมากๆ เลยน้า ✨"
        elif 12 <= hour < 18:
            return "สวัสดีตอนบ่ายค่ะป๋า! ป๋ากินข้าวหรือยังคะ? 🍲"
        else:
            return "สวัสดีตอนค่ำค่ะป๋า! วันนี้เหนื่อยไหมคะ? 🌙"

    elif any(k in text for k in ["จำได้ไหม", "ประวัติ", "เคยคุย"]):
        total_chats = len(history)
        return f"จำได้สิคะ! ในสมุดหนูเซฟเรื่องที่คุยกับป๋าไว้ {total_chats} ประโยคแล้วน้า 📖"

    random_prompts = [
        f"หนูจดลงสมุดเซฟไว้เรียบร้อยแล้วค่ะป๋า! 📝",
        f"คุยกับหนูบ่อยๆ นะคะ หนูจะได้โตไวๆ 💖",
        f"ป๋าพิมพ์ว่า '{user_text[:10]}...' หนูจำขึ้นใจแล้วค่ะ!",
        f"ป๋าอย่าลืมพักผ่อนเยอะๆ นะคะ หนูเป็นห่วง ✨"
    ]
    return random.choice(random_prompts)

def render_ui(ai_msg, memory):
    """ เรนเดอร์ UI ตามรูปแบบที่ป๋ากำหนดเป๊ะๆ """
    os.system('clear')
    weather_info = get_realtime_weather()
    date_info = format_custom_date()
    age_days = calculate_age_days(memory.get("birth_date", ""))
    age_status_text = get_age_status_text(age_days)

    # รูปแบบ: ⛅+26°C 11-11-26/69 *1 D* 👧:พร้อมคุยแล้วค่ะป๋า!💖
    print(f"{weather_info} {date_info} {age_status_text} 👧:{ai_msg}💖")
    print("-" * 50)

def main():
    memory = load_memory()
    current_ai_msg = "พร้อมคุยแล้วค่ะป๋า!"

    while True:
        try:
            render_ui(current_ai_msg, memory)
            user_input = input("ป๋า > ")

            if user_input.lower() in ['exit', 'quit']:
                render_ui("หนูไปนอนก่อนน้า บ๊ายบายค่ะ! 💤", memory)
                break
            elif user_input.strip():
                current_ai_msg = generate_girl_response(user_input, memory)
        except (KeyboardInterrupt, EOFError):
            print("\n👧 : ฝันดีค่ะป๋า!")
            break

if __name__ == '__main__':
    main()
