    if os.path.exists(MEMORY_FILE):
        try:
            with open(MEMORY_FILE, 'r', encoding='utf-8') as f:
                data = json.load(f)
        except Exception:
            data = {}
    elif os.path.exists(BACKUP_MEMORY_FILE):
        try:
            with open(BACKUP_MEMORY_FILE, 'r', encoding='utf-8') as f:
