    else:
        reply = f"รับทราบคำสั่ง '{raw_text}' ค่ะป๋า! บันทึกลง memory.json ({mem_size_kb:.1f} KB) เรียบร้อยแล้ว ❤️"

    return f"{header}\n\n{reply}"

