from flask import Flask, render_template, request, jsonify
import subprocess, os, socket, json, urllib.request
from datetime import datetime

app = Flask(__name__)
MEMORY_FILE = os.path.expanduser('~/ai_girl_bot/memory.json')

def load_memory():
    if os.path.exists(MEMORY_FILE):
        try:
            with open(MEMORY_FILE, 'r', encoding='utf-8') as f:
                return json.load(f)
        except Exception:
            pass
    default_mem = {"birth_date": "2026-11-01", "chat_history": [], "user_name": "ป๋า"}
    save_memory(default_mem)
    return default_mem

def save_memory(data):
    os.makedirs(os.path.dirname(MEMORY_FILE), exist_ok=True)
    with open(MEMORY_FILE, 'w', encoding='utf-8') as f:
        json.dump(data, f, ensure_ascii=False, indent=2)

def get_weather():
    try:
        req = urllib.request.Request('https://wttr.in/?format=%C|%t', headers={'User-Agent': 'curl/7.68.0'})
        with urllib.request.urlopen(req, timeout=2) as res:
            cond, temp = res.read().decode('utf-8').strip().split('|')
            return f"🌤️ {cond.strip()} {temp.strip()}"
    except Exception:
        return "🌡️ Offline"

def think_like_bot(user_text):
    mem = load_memory()
    now = datetime.now()
    try:
        b_date = datetime.strptime(mem.get("birth_date", "2026-11-01"), '%Y-%m-%d')
        age_days = max(1, (now - b_date).days + 1)
    except Exception:
        age_days = 1

    history = mem.get("chat_history", [])
    history.append({"time": now.strftime('%Y-%m-%d %H:%M:%S'), "user": user_text})
    if len(history) > 30:
        history.pop(0)
    mem["chat_history"] = history
    save_memory(mem)

    text = user_text.strip().lower()
    weather = get_weather()
    header = f"👧 [บอทตัวน้อย: อายุ {age_days} วัน | {weather} | ความจำ {len(history)} รายการ]"

    if any(k in text for k in ["เวลา", "กี่โมง", "ยามไหน"]):
        reply = f"ตอนนี้เวลา {now.strftime('%H:%M:%S น.')} ค่ะป๋า! ⏰"
    elif any(k in text for k in ["อายุ", "กี่วัน", "โตยัง"]):
        reply = f"หนูอายุ {age_days} วันแล้วนะคะป๋า! 💖"
    elif any(k in text for k in ["จำได้ไหม", "ประวัติ", "เคยคุย"]):
        last_msgs = [h['user'] for h in history[-4:-1]]
        reply = f"จำได้ค่ะ! ก่อนหน้านี้ป๋าเพิ่งสั่งหนูว่า: {', '.join(last_msgs) if last_msgs else 'เพิ่งเริ่มคุยกันรอบนี้เลยค่ะ'} 🧠"
    elif any(k in text for k in ["สวัสดี", "หวัดดี", "ดีจ้า", "ว่าไง"]):
        reply = "สวัสดีค่ะป๋า! ช่องนี้คุยส่วนตัวกับหนูได้เลยนะคะ ✨"
    else:
        reply = f"รับทราบคำสั่ง '{user_text}' ค่ะป๋า! บันทึกลงสมองเรียบร้อยแล้ว ❤️"

    return f"{header}\n\n💬 {reply}"

